from pathlib import Path
import json,hashlib,html

root=Path(__file__).resolve().parents[1];out=root/'output/arc-verification'
read=lambda name:json.loads((out/name).read_text(encoding='utf-8-sig'))
unit=read('unit-results.json');assert unit['success'] and unit['numPassedTests']==377
files=['api-results.json','cutting-results.json','export-label-results.json','coordinate-results.json','ui-results.json','built-results.json'];counts={}
for name in files:
    r=read(name);assert not r.get('errors') and not r.get('cloud');assert all(x['status']=='PASS' for x in r['results']);counts[name]=len(r['results'])
total=unit['numPassedTests']+sum(counts.values());assert total==400
for name in ['demo-build.log','production-build.log']:assert 'built in' in (out/name).read_text('utf-8-sig')
comparison=read('config-comparison.json')
for name,data in comparison.items():assert data['finalSha256']==hashlib.sha256((root/name).read_bytes()).hexdigest()
changed={name:data for name,data in comparison.items() if data['baselineSha256']!=data['finalSha256']}
assert not changed,'Inspect and preserve any concurrent configuration change before publishing this report'
checkpoint=read('checkpoint-verification.json');assert checkpoint['status']=='PASS'
pdf=read('pdf-results.json');assert pdf['renderedPages']==30 and all(r['status']=='PASS' for r in pdf['results'])
excel=read('render-results.json');assert excel['status']=='PASS' and excel['views']==4
ctx=read('context.json')
for artifact in ctx['artifacts']+ctx.get('previousArtifacts',[]):
    data=(out/artifact['local']).read_bytes();assert len(data)==artifact['size'] and hashlib.sha256(data).hexdigest()==artifact['sha256']
backup=out/'BS67-backup.zip'
summary={'version':'0.31.0','status':'PASS for tested software scope only','softwareScenarios':total,'unitTests':377,'testGroups':counts,'pdfPages':30,'workbookViews':4,'fullSystemAcceptance':False,'engineeringAccepted':False,'productionAccepted':False,'rulesDeployment':'User managed; explicitly declined','rulesFilesEditedByThisIncrement':False,'cloudChangesByThisIncrement':False,'configurationComparison':comparison,'checkpoint':checkpoint,'currentExportArtifacts':ctx['artifacts'],'preservedPreviousArtifacts':ctx.get('previousArtifacts',[]),'backupSha256':hashlib.sha256(backup.read_bytes()).hexdigest(),'nativeExcelPrintingVerified':False}
(out/'verification-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),'utf8')
images=[('built-envelope.png','รูป 67 สองเส้น: A ส่วนโค้ง / R ด้านใน'),('built-3d.png','ตำแหน่งจริงและการทำซ้ำตามระนาบ — รุ่น build'),('built-mobile.png','หน้าจอ 390px: C01 และพิกัดต้น/กลาง/ปลาย'),('excel-bbs.png','Excel จริง: ตาราง BBS พร้อมรูปและมิติตามรูป'),('excel-rebar.png','Excel จริง: สรุปเหล็ก18เส้น / 19.650m / 31.014kg'),('excel-arc.png','Excel จริง: A จากรัศมีและมุมกวาด พร้อมยาวตัดที่ตรึงไว้'),('excel-frame.png','Excel จริง: ศูนย์กลาง ระนาบ ช่วงทำซ้ำและคำสั่ง Table5'),('pdf-A3-contact.png','PDF รูปผิวเหล็ก A3 — 4 หน้า'),('pdf-A1-contact.png','PDF รูปผิวเหล็ก A1 — 4 หน้า'),('pdf-A4-contact.png','PDF ตารางและภาคผนวก A4 — 5 หน้า'),('pdf-coordinates-A3-contact.png','PDF พิกัด/การคำนวณ A3 — 9 หน้า'),('pdf-coordinates-A1-contact.png','PDF พิกัด/การคำนวณ A1 — 8 หน้า')]
for name,_ in images:assert (out/name).is_file()
gallery=''.join(f'<figure><a href="{name}"><img src="{name}" alt="{title}" loading="lazy"></a><figcaption>{title}</figcaption></figure>' for name,title in images)
downloads=[('BS67-draft.xlsx','Excel BBS'),('BS67-large-draft.xlsx','Excel รัศมีใหญ่'),('BS67-A3-draft.pdf','รูปผิวเหล็ก A3'),('BS67-A1-draft.pdf','รูปผิวเหล็ก A1'),('BS67-coordinates-A3-draft.pdf','พิกัด A3'),('BS67-coordinates-A1-draft.pdf','พิกัด A1'),('BS67-A4-draft.pdf','ตาราง A4'),('BS67-backup.zip','Backup ทดสอบ')]
links=''.join(f'<a class="download" href="{name}">{label}</a>' for name,label in downloads)
checks=''.join(f'<li>{html.escape(r["name"])}</li>' for name in files for r in read(name)['results'])
doc=f'''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BOQ & BBS v0.31 — ผลการพัฒนา</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#f3f7f5;color:#203940;font:16px/1.75 system-ui,"Sarabun",sans-serif}}main{{max-width:1180px;margin:auto;padding:32px}}header,section{{background:white;border:1px solid #dce6e1;border-radius:14px;padding:28px;margin-bottom:22px}}h1{{font-size:30px;line-height:1.35}}h2{{font-size:23px}}a{{color:#176b55}}.eyebrow{{color:#537267;font-weight:650}}.status{{background:#fff2d6;color:#714d17;padding:16px;border-radius:8px}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}}.stat{{background:#edf5f0;padding:16px;border-radius:8px}}.stat strong{{display:block;font-size:27px}}.downloads{{display:flex;flex-wrap:wrap;gap:10px}}.download{{border:1px solid #b9cfc4;padding:8px 13px;border-radius:6px;text-decoration:none}}.gallery{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}figure{{margin:0;border:1px solid #dce6e1;border-radius:9px;padding:10px;min-width:0}}img{{width:100%;height:280px;object-fit:contain;background:#fafcfb}}figcaption{{font-size:14px;padding-top:8px}}table{{border-collapse:collapse;width:100%}}th,td{{padding:12px;text-align:left;border-bottom:1px solid #dce6e1}}th{{background:#edf5f0}}.scroll{{overflow:auto}}code{{overflow-wrap:anywhere}}li{{margin-bottom:9px}}details{{margin-top:18px}}small{{color:#5d756b}}@media(max-width:640px){{main{{padding:12px}}header,section{{padding:18px}}h1{{font-size:24px}}.stats{{grid-template-columns:1fr 1fr}}.gallery{{grid-template-columns:1fr}}img{{height:auto;max-height:600px}}}}
</style><main><header><div class="eyebrow">FORM BOQ & BBS · v0.31 · 12 ตุลาคม 2026</div><h1>เพิ่มเหล็กส่วนโค้ง Shape 67 พร้อมไฟล์ส่งออกจริง</h1><p>ใช้มาตรฐานขั้นต่ำจาก BS8666 ที่ผู้ใช้ให้ไว้ แยกความยาวส่วนโค้ง A รัศมีด้านใน R และรัศมีแนวศูนย์กลาง พร้อมแสดงตำแหน่งในสมาชิกและคำสั่งการจัดหาเหล็กจาก Table5</p><div class="status"><b>ผ่านเฉพาะขอบเขตซอฟต์แวร์ที่ทดสอบ — ยังไม่ผ่านการตรวจรับระบบเต็มหรือวิศวกรรม</b><br>ตัวอย่างในรอบนี้เป็นข้อมูลทดสอบในเครื่อง ไม่มีชุดงานเจ้าของโครงการจริงที่อนุมัติ Issued และการใช้สต็อก Production ยังปิดอยู่</div><div class="stats"><div class="stat"><strong>{total}</strong>กรณีซอฟต์แวร์ผ่าน</div><div class="stat"><strong>30</strong>หน้า PDF จริงที่เรนเดอร์</div><div class="stat"><strong>4</strong>ช่วงตาราง Excel ที่ตรวจภาพ</div><div class="stat"><strong>0</strong>deploy Rules ในรอบนี้</div></div><div class="downloads">{links}</div></header>
<section><h2>การใช้งานที่เพิ่ม</h2><ul><li>ในสมาชิก เปิดหรือเพิ่ม Mark แล้วเลือกเครื่องมือส่วนโค้ง 67 กรอก A และ R ด้านในทีละ5mm เลือก XY/XZ/YZ สร้างรูป ตรวจขนาดผิวนอก/ซี่บั้ง และบันทึกทั้งชุดเหล็กกับสมาชิก</li><li>แก้ศูนย์กลางเส้นแรกและช่วงทำซ้ำตามแนวตั้งฉากของระนาบได้ เส้นเดียวอยู่ที่ศูนย์กลางที่กรอกจริง ไม่ย้ายไปกึ่งกลางช่วงเอง การแก้รูป/ตำแหน่งล้างการยืนยันให้ตรวจใหม่</li><li>ชุดกฎขั้นต่ำรุ่น5 ใช้กับโครงการใหม่ โครงการเดิมรับรุ่น5อย่างชัดเจนใน General Spec ก่อนใช้งาน รูปและตัวเลข Frozen รุ่น1/2/3/4 คงฐานเดิม</li><li>หน้าจอและแบบแยก A ส่วนโค้ง/R ด้านในจาก R ศูนย์กลาง โดยเส้นบอก A โค้งตามรูป C01 คือส่วนโค้งเดียวและ P1/P2/P3 คือต้น/กลาง/ปลายจริง ไม่มีการสร้างมุมดัดจากจุดแสดงผล</li><li>Excel เพิ่ม Curve Geometry เก็บรัศมี มุมกวาด ศูนย์กลาง ระนาบ ช่วงทำซ้ำ และสูตร A ตรวจย้อนกลับได้ ตาราง BBS แสดงมิติตามรูปและรูปส่วนโค้ง พร้อมยาวตัด/จำนวนที่ตรึงไว้</li></ul><p>คู่มือ: <a href="../../docs/BS_ARC.md">การสร้างและตรวจรูป67</a></p></section>
<section><h2>ตัวเลขที่ตรวจอิสระ</h2><div class="scroll"><table><thead><tr><th>Mark / ข้อมูล mm</th><th>R ศูนย์กลาง / มุมกวาด</th><th>A จริง</th><th>ยาวตัดขึ้นทีละ25mm</th></tr></thead><tbody><tr><td>ARC: nominal/outside16, inside R1000</td><td>1008 / 57.125256°</td><td>1005</td><td>1025</td></tr><tr><td>RIB: nominal16/outside20, inside R1000</td><td>1010 / 70.910618°</td><td>1250</td><td>1250</td></tr><tr><td>SITE: nominal/outside16, inside R7510</td><td>7518 / 7.621147°</td><td>1000</td><td>1000</td></tr></tbody></table></div><p>ยาวจริง = R ศูนย์กลาง × มุมกวาดเป็นเรเดียน ไม่รวมความยาวคอร์ดหรือหักรัศมีจากจุดที่ใช้แสดงภาพ Nominal16ใช้คำนวณน้ำหนัก ส่วนขนาดผิวนอก16/20ใช้กำหนดแนวผิวและรัศมี</p><p>Frozen: 3สมาชิก ×2เส้นต่อMark =18เส้น / 19650mm / 31.014kg ส่วน Working เปลี่ยนเป็น5สมาชิก ได้30เส้น / 32750mm Worker แผนตัดจริงรับสิบเส้นต่อยาว1025/1250/1000mm ในขอบเขตสมาชิกที่เลือก ไม่มีการคูณซ้ำและไม่เปลี่ยน Frozen เดิม</p></section>
<section><h2>การอ่าน Table5 และข้อจำกัดของรูป</h2><p>สำหรับเหล็กชนิด bar16mm ขีดจำกัด Table5 คือ7500mm รัศมีด้านในที่มากกว่าขีดจำกัดแสดง “Supply straight / form during placing”; เท่ากันยังเป็น “Preformed radius required” ระบบแสดงคำสั่งจัดหาโดยคงรูปโค้งที่ติดตั้งและยาวตัดเดิม ชนิด/ขนาดที่ยังเทียบมาตรฐานไม่ได้ยังรอตรวจ</p><p>รูป67ส่วนโค้งล้วนไม่ใช้ข้อกำหนดช่วงตรงปลาย5d/ระหว่างดัด4d หรือ Table3 r-minimum แบบรูปที่มีปลายตรง และไม่มีมิติอิสระ A/R ใน Table1 ขอบเขตนี้ไม่รับรองรัศมีโครงสร้าง ACI งานดัดหน้างาน หรือการผลิตครบทุกข้อของ BS</p><p>ตรวจตำแหน่งด้วยขอบเขตวงกลมจริงร่วมกับ solid/void/cover การแสดงภาพใช้จุดตามวงกลม เป้าหมาย sagitta0.1mm และไม่เกิน720ช่วง โดยเพิ่มค่าความคลาดเคลื่อนที่เปิดเผยเข้าตรวจ cover อย่างระมัดระวัง ไม่ใช้ความยาวช่วงเหล่านี้เป็นปริมาณ ขีดจำกัดรัศมี100km เป็นขอบเขตตัวเลขของแอป ไม่ใช่มาตรฐาน</p><p>วงแหวน360°ยังต้องกำหนดรูป/รอยต่อ/ระยะทาบแยก เครื่องมือสร้างนี้รับส่วนโค้งเปิดเท่านั้น เส้นรัศมีในรูป NTS อาจตัดย่อเพื่อให้อ่านได้ แต่ค่าตัวเลขและพิกัดจริงอยู่ในตาราง</p></section>
<section><h2>ขอบเขตหลักฐาน</h2><p>377 unit +8 เชื่อมต่อ/ส่งออก/กู้คืน +1 แผนตัด +1 ตรวจหัวตาราง Excel +1 ชุดส่งออกพิกัด/A4 +6 หน้าจอ dev +6 หน้าจอ build ={total} กรณี การตรวจ PDF30หน้าและ Excel4ช่วงตารางนับแยกจากจำนวนนี้ Build ทั้ง demo และค่าตั้ง Production ผ่าน แต่ยังไม่ได้ deploy</p><ul><li>ไฟล์ทั้งหมดสร้างผ่าน generateJob/upload/download ของระบบจริง เทียบขนาดและ SHA256 กับงานส่งออกที่เก็บไว้ ไม่มี diagnostic ที่สร้างแทน PDFของแอป</li><li>PDF รูปผิวเหล็ก A3/A1 อย่างละ4หน้า พิกัด/การคำนวณ A3เก้าหน้า A1แปดหน้า และ A4ห้าหน้า ตรวจขนาดกระดาษ ขอบเขตข้อความ และภาพทุกชุด</li><li>Excel จริงนำเข้ามาคำนวณใหม่ เปลี่ยนมุมกวาดชั่วคราวในสำเนาเพื่อตรวจสูตร A โดยยาวตัด Frozen ไม่เปลี่ยน จากนั้นตรวจสูตรเชื่อมยาวตัด BBSกับตารางพิมพ์และคืนค่าก่อนตรวจภาพ ไม่อ้างการพิมพ์จาก Microsoft Excelจริง</li><li>ข้อมูลรัศมีใหญ่เก็บพารามิเตอร์วงกลมครบใน Curve Geometry หาก JSONจุดแสดงผลเกินเซลล์เดิม จะระบุว่าเว้นจุดแสดงผลอย่างชัดเจน ไม่ตัดข้อมูลเงียบ ๆ</li><li>Backup ZIP/Restoreจริงรักษา primitive/Specรุ่น5 แต่ล้างการยืนยัน ประวัติ Revisionคงเป็น importedHistoryสำหรับอ้างอิง พร้อมไฟล์เดิม ไม่กลายเป็น Issuedและไม่คืน ACLต้นทาง</li><li>ผู้ใช้ viewerอ่านโครงการที่ได้รับมอบหมายได้แต่แก้รูป/Specไม่ได้ โครงการอื่นปฏิเสธการอ่าน ทั้งหมดใช้บัญชี/ฐานข้อมูล emulator ไม่มีคำขอCloudหรือ browser error ที่พบในชุดทดสอบ</li></ul><details><summary>รายการทดสอบเชื่อมต่อและหน้าจอ</summary><ul>{checks}</ul></details><p><a href="verification-summary.json">ผลตรวจแบบอ่านด้วยเครื่อง</a> · <a href="pdf-results.json">การตรวจ PDF</a> · <a href="render-results.json">การตรวจ Excel</a></p></section>
<section><h2>ภาพจากระบบและไฟล์ส่งออก</h2><p>คลิกภาพเพื่อดูขนาดเต็ม ภาพตาราง Curve Geometry แบ่งเป็นสองช่วงเพื่อให้อ่านพารามิเตอร์ได้ชัด ไม่ใช่การรับรองการพิมพ์ทั้ง worksheet</p><div class="gallery">{gallery}</div></section>
<section><h2>มาตรฐานและข้อมูลที่รักษาไว้</h2><p>ที่มา: <a href="../../Referrence/BS%208666.pdf">BS8666 ที่ผู้ใช้ให้ไว้</a> ฉบับ BS8666:2000+Amd1/2; Table1หน้า8 และ clause10/Table5หน้า13 (หน้า PDF12/17) อ่านทั้งข้อความและรูป ไม่อ้างเป็นปีฉบับล่าสุดหรือการตรวจครบมาตรฐาน</p><p><code>SHA256 9c6fa5d0bafd0a8761f14d1611c582d5db7d89710eaaf0910b5dc7c493e0cb43</code></p><p>เทียบ AuthContext, authService, clientCommands, Firestore/Storage Rules, firebase.json และ .env รวม7ไฟล์กับฐานเริ่มรอบนี้แล้วคงเดิม งานv0.31ไม่เขียน Rules/.env ไม่เพิ่ม Cloud Functions ไม่ deployหรือแก้ข้อมูลCloud ผู้ใช้กำหนดและ deploy Rulesเอง ผล emulatorไม่ยืนยัน RulesปัจจุบันบนCloud ดู <a href="config-comparison.json">หลักฐานเทียบไฟล์ตั้งค่า</a></p><p>checkpointใหม่: <code>{html.escape(checkpoint['checkpoint'])}</code> สำรอง Auth/Firestore/Storageในเครื่อง ตรวจขนาด/MD5ของ Storage{checkpoint['storageBlobs']}รายการ และรักษา SHA256ของ{checkpoint['previousV30BlobsSha256Preserved']}รายการเดิมv0.30ทั้งหมด ไม่มีการแทน .emulator-data หรือ reimport และไม่อ้างการเทียบฐานข้อมูลทั้งชุด/การกู้คืน Production ดู <a href="checkpoint-verification.json">ผลตรวจ checkpoint</a></p></section>
<section><h2>งานเดิมที่ยังต้องทำก่อนใช้จริง</h2><ul><li>BS shapes33/51/77, กฎ ACI318 hooks/lap/development, การชดเชย toleranceสะสม และชุดกรณีที่ผู้รับผิดชอบรับรอง</li><li>ชุดข้อมูล GULF/แบบเจ้าของงานจริง รูปทรงและรายละเอียดเพิ่มเติม การตรวจรับกรอบชื่อแบบ A3/A1 และการพิมพ์ Excelจริง</li><li>การทำงาน Productionกับ Rulesที่ผู้ใช้จัดการ บัญชีจริง โหลดโครงการจริง การปฏิบัติการและกู้คืน ต้องตรวจแยกก่อนเปิด Issuedหรือผลิต</li></ul><small>รายงานนี้เป็นหลักฐานการพัฒนาในรอบv0.31 งานตามข้อกำหนดเดิมทั้งระบบยังไม่จบ และยังไม่พร้อมออก BBSใช้ก่อสร้าง</small></section></main></html>'''
(out/'DEVELOPMENT_REPORT.html').write_text(doc,'utf8');print(f'PASS: report generated from {total} scoped software scenarios')
